changeSet.sql:
ALTER TABLE agent_action ADD COLUMN authorization_stamp jsonb DEFAULT jsonb_build_object('workspace', 0) NOT NULL,
    ADD CONSTRAINT ck_agent_action_authorization_stamp CHECK ((jsonb_typeof(authorization_stamp) = 'object'
        AND jsonb_typeof(authorization_stamp -> 'workspace') = 'number'
        AND (authorization_stamp ->> 'workspace') ~ '^[0-9]{1,19}$'
        AND (authorization_stamp ->> 'workspace')::numeric <= 9223372036854775807) IS TRUE) NOT VALID;
CREATE TRIGGER agent_action_authorization_stamp_fixed AFTER UPDATE OF authorization_stamp ON agent_action
    FOR EACH ROW EXECUTE FUNCTION guard_authorization_stamp();
ALTER TABLE agent_action DROP CONSTRAINT ck_agent_action_stop_reason;
ALTER TABLE agent_action ADD CONSTRAINT ck_agent_action_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN
    ('COMPLETED','REJECTED','RECIPIENT_UNAVAILABLE','NOT_CONFIGURED','WITHDRAWN','SILENCED','ATTEMPTS_EXHAUSTED','EXPIRED',
     'ABSENT','WRITE_UNCONFIRMED','LEASE_LOST_AFTER_WRITE','AUTHORITY_CHANGED')) NOT VALID;

