changeSet.sql:
ALTER TABLE account ADD COLUMN authority_generation bigint DEFAULT 0 NOT NULL,
    ADD CONSTRAINT ck_account_authority_generation CHECK (authority_generation >= 0);
CREATE FUNCTION ai_choice_narrows_authority() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE public.account SET authority_generation = authority_generation + 1 WHERE id = NEW.id;
    RETURN NULL;
END $$;
-- AFTER, not BEFORE: a BEFORE row trigger makes PostgreSQL lock the row FOR UPDATE whenever an UPDATE lists a key
-- column, as an entity flush does, and that lock blocks every foreign key check on the account until commit.
CREATE TRIGGER account_ai_choice_narrows_authority AFTER UPDATE OF ai_choice ON public.account
    FOR EACH ROW WHEN (NEW.ai_choice IS DISTINCT FROM OLD.ai_choice
        AND (NEW.ai_choice IS NULL
             OR NEW.ai_choice = 'NO_AI'
             OR (NEW.ai_choice = 'IN_HOUSE_ONLY' AND OLD.ai_choice = 'CLOUD')))
    EXECUTE FUNCTION ai_choice_narrows_authority();

rollback.sql:
DROP TRIGGER account_ai_choice_narrows_authority ON account;
DROP FUNCTION ai_choice_narrows_authority();
ALTER TABLE account DROP COLUMN authority_generation;

changeSet.sql:
CREATE FUNCTION public.authorization_stamp_valid(stamp jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
    SELECT jsonb_typeof(stamp) = 'object'
        AND jsonb_typeof(stamp -> 'workspace') = 'number'
        AND (stamp ->> 'workspace') ~ '^[0-9]{1,19}$'
        AND (stamp ->> 'workspace')::numeric <= 9223372036854775807
        AND (NOT (stamp ? 'accounts')
             OR (jsonb_typeof(stamp -> 'accounts') = 'object'
                 AND NOT EXISTS (
                     SELECT 1 FROM pg_catalog.jsonb_each(stamp -> 'accounts') AS person(account, generation)
                      WHERE person.account !~ '^[0-9]{1,19}$'
                         OR jsonb_typeof(person.generation) <> 'number'
                         OR (person.generation #>> '{}') !~ '^[0-9]{1,19}$'
                         OR (person.generation #>> '{}')::numeric > 9223372036854775807)))
$$;
ALTER TABLE agent_run DROP CONSTRAINT ck_agent_run_authorization_stamp;
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_authorization_stamp
    CHECK ((jsonb_typeof(authorization_stamp) = 'object' AND public.authorization_stamp_valid(authorization_stamp)) IS TRUE) NOT VALID;
ALTER TABLE agent_action DROP CONSTRAINT ck_agent_action_authorization_stamp;
ALTER TABLE agent_action ADD CONSTRAINT ck_agent_action_authorization_stamp
    CHECK ((jsonb_typeof(authorization_stamp) = 'object' AND public.authorization_stamp_valid(authorization_stamp)) IS TRUE) NOT VALID;
ALTER TABLE agent_action DISABLE TRIGGER agent_action_authorization_stamp_fixed;
UPDATE agent_action SET authorization_stamp = authorization_stamp
        || jsonb_build_object('accounts', jsonb_build_object(subject_account_id::text, 0))
    WHERE kind IN ('DELIVER_FEEDBACK', 'EDIT_FEEDBACK', 'RETRACT_FEEDBACK', 'SLACK_POST')
      AND workspace_id IS NOT NULL AND subject_account_id IS NOT NULL
      AND state IN ('PROPOSED', 'ADMITTED', 'EXECUTING');
ALTER TABLE agent_action ENABLE TRIGGER agent_action_authorization_stamp_fixed;
ALTER TABLE agent_run DISABLE TRIGGER agent_run_authorization_stamp_fixed;
UPDATE agent_run AS run SET authorization_stamp = run.authorization_stamp
        || jsonb_build_object('accounts', jsonb_build_object(owner.account_id::text, 0))
    FROM conversation AS owner
    WHERE run.kind IN ('TURN', 'DIGEST') AND run.state <> 'ENDED'
      AND owner.workspace_id = run.workspace_id AND run.concurrency_key = 'conversation:' || owner.id::text;
ALTER TABLE agent_run ENABLE TRIGGER agent_run_authorization_stamp_fixed;

