DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM public.agent_action WHERE stop_reason = 'AUTHORITY_CHANGED') THEN
  RAISE EXCEPTION 'Restore the verified pre-upgrade backup: actions record that their access changed';
